/**
 * Runner Compatibility Integration Test
 * 
 * Verifies that config.js generated by serializeConfig is compatible
 * with the performancetest.js runner.
 * 
 * Tests:
 * - Task 8.1: Verificar compatibilidad del output con performancetest.js
 * - Requirements: 1.3, 3.5, 3.6
 * 
 * This test:
 * 1. Generates a config.js using serializeConfig
 * 2. Writes it to disk as a temporary ES module
 * 3. Imports the module dynamically
 * 4. Verifies profile filtering logic works (endpoint[scenarioName])
 */

import { describe, it, expect, beforeAll, afterAll } from "vitest";
import { serializeConfig } from "../../src/services/serializeConfig.js";
import type { Config } from "../../src/models/config.types.js";
import { writeFileSync, unlinkSync } from "fs";
import { fileURLToPath } from "url";
import { dirname, join } from "path";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Temporary config file path
const tempConfigPath = join(__dirname, "../../temp-test-config.js");

describe("Runner Compatibility - Task 8.1", () => {
  let generatedConfig: Config;

  beforeAll(() => {
      // Create a generic config for runner compatibility
    generatedConfig = {
      endpoints: [
        {
          name: "Create resource",
          description: "Creates a generic resource",
          url: "https://example.test/api/resource",
          method: "POST",
          payload: {
            name: "Sample resource",
            value: "example",
          },
          headers: {
            "Content-Type": "application/json",
            "X-Test-Client": "example",
          },
          expectedStatus: 200,
          maxRetries: 3,
          thinkTimeSeconds: 1,
          loadtest: {
            stages: [
              { duration: "30s", target: 10 },
              { duration: "2m", target: 10 },
              { duration: "30s", target: 0 },
            ],
            thresholds: {
              http_req_duration: ["p(95) < 2000"],
              http_req_failed: ["rate < 0.01"],
              waiting_time: ["avg < 1600"],
              Errors: ["count < 5"],
            },
          },
          stresstest: {
            stages: [
              { duration: "30s", target: 50 },
              { duration: "1m", target: 50 },
              { duration: "30s", target: 0 },
            ],
            thresholds: {
              http_req_duration: ["p(95) < 5000"],
              Errors: ["count < 20"],
            },
          },
        },
        {
          url: "https://example.test/api/another",
          method: "GET",
          expectedStatus: 200,
          maxRetries: 2,
          thinkTimeSeconds: 0.5,
          capacitytest: {
            stages: [
              { duration: "1m", target: 20 },
              { duration: "30s", target: 0 },
            ],
            thresholds: {
              http_req_duration: ["p(95) < 3000"],
            },
          },
          stabilitytest: {
            stages: [
              { duration: "30s", target: 10 },
              { duration: "2m", target: 10 },
              { duration: "30s", target: 0 },
            ],
            thresholds: {
              http_req_failed: ["rate < 0.01"],
            },
          },
        },
      ],
    };

    // Generate and write config.js
    const serialized = serializeConfig(generatedConfig);
    writeFileSync(tempConfigPath, serialized, "utf-8");
  });

  afterAll(() => {
    // Clean up temporary file
    try {
      unlinkSync(tempConfigPath);
    } catch (error) {
      // File might not exist, ignore
    }
  });

  it("8.1.1: should generate a valid ES module config.js", () => {
    const serialized = serializeConfig(generatedConfig);

    // Verify ES module format
    expect(serialized).toContain("export default");
    expect(serialized).toContain("endpoints:");

    // Verify it's syntactically valid JavaScript (no syntax errors)
    expect(() => {
      // This will throw if syntax is invalid
      new Function(serialized.replace("export default", "return"));
    }).not.toThrow();
  });

  it("8.1.2: should be importable as ES module", async () => {
    // Dynamic import of the generated config
    const imported = await import(`${tempConfigPath}?cache=${Date.now()}`);

    // Verify structure matches expected contract
    expect(imported.default).toBeDefined();
    expect(imported.default.endpoints).toBeDefined();
    expect(Array.isArray(imported.default.endpoints)).toBe(true);
  });

  it("8.1.3: should support profile filtering by TEST_TYPE (loadtest)", async () => {
    const imported = await import(`${tempConfigPath}?cache=${Date.now()}`);
    const config = imported.default;

    const scenarioName = "loadtest";
    const endpoints = config.endpoints.filter(
      (ep: any) => ep[scenarioName]
    );

    // First endpoint has loadtest, second doesn't
    expect(endpoints.length).toBe(1);
    expect(endpoints[0].url).toBe("https://example.test/api/resource");
    expect(endpoints[0].loadtest).toBeDefined();
    expect(endpoints[0].loadtest.stages).toBeDefined();
    expect(endpoints[0].loadtest.thresholds).toBeDefined();
  });

  it("8.1.4: should support profile filtering by TEST_TYPE (stresstest)", async () => {
    const imported = await import(`${tempConfigPath}?cache=${Date.now()}`);
    const config = imported.default;

    const scenarioName = "stresstest";
    const endpoints = config.endpoints.filter(
      (ep: any) => ep[scenarioName]
    );

    // First endpoint has stresstest, second doesn't
    expect(endpoints.length).toBe(1);
    expect(endpoints[0].url).toBe("https://example.test/api/resource");
    expect(endpoints[0].stresstest).toBeDefined();
  });

  it("8.1.5: should support profile filtering by TEST_TYPE (capacitytest)", async () => {
    const imported = await import(`${tempConfigPath}?cache=${Date.now()}`);
    const config = imported.default;

    const scenarioName = "capacitytest";
    const endpoints = config.endpoints.filter(
      (ep: any) => ep[scenarioName]
    );

    // Second endpoint has capacitytest, first doesn't
    expect(endpoints.length).toBe(1);
    expect(endpoints[0].url).toBe("https://example.test/api/another");
    expect(endpoints[0].capacitytest).toBeDefined();
  });

  it("8.1.6: should support profile filtering by TEST_TYPE (stabilitytest)", async () => {
    const imported = await import(`${tempConfigPath}?cache=${Date.now()}`);
    const config = imported.default;

    const scenarioName = "stabilitytest";
    const endpoints = config.endpoints.filter(
      (ep: any) => ep[scenarioName]
    );

    // Second endpoint has stabilitytest, first doesn't
    expect(endpoints.length).toBe(1);
    expect(endpoints[0].url).toBe("https://example.test/api/another");
    expect(endpoints[0].stabilitytest).toBeDefined();
  });

  it("8.1.7: should preserve custom metrics in thresholds", async () => {
    const imported = await import(`${tempConfigPath}?cache=${Date.now()}`);
    const config = imported.default;

    const endpoint = config.endpoints[0];
    const thresholds = endpoint.loadtest.thresholds;

    // Verify custom metrics are preserved exactly
    expect(thresholds.waiting_time).toBeDefined();
    expect(thresholds.Errors).toBeDefined();
    
    // Verify built-in metrics are preserved
    expect(thresholds.http_req_duration).toBeDefined();
    expect(thresholds.http_req_failed).toBeDefined();

    // Verify threshold expressions are arrays of strings
    expect(Array.isArray(thresholds.waiting_time)).toBe(true);
    expect(thresholds.waiting_time[0]).toBe("avg < 1600");
  });

  it("8.1.8: should preserve endpoint fields required by runner", async () => {
    const imported = await import(`${tempConfigPath}?cache=${Date.now()}`);
    const config = imported.default;

    const endpoint = config.endpoints[0];

    // Verify all required fields are present
    expect(endpoint.url).toBe("https://example.test/api/resource");
    expect(endpoint.method).toBe("POST");
    expect(endpoint.expectedStatus).toBe(200);
    expect(endpoint.maxRetries).toBe(3);
    expect(endpoint.thinkTimeSeconds).toBe(1);
    
    // Verify optional fields
    expect(endpoint.payload).toBeDefined();
    expect(endpoint.headers).toBeDefined();
    expect(endpoint.name).toBe("Create resource");
    expect(endpoint.description).toBe("Creates a generic resource");
  });

  it("8.1.9: should handle endpoints with no profiles", async () => {
    // Create config with an endpoint that has no profiles
    const configWithoutProfiles: Config = {
      endpoints: [
        {
          url: "https://example.test/api/noprofiles",
          method: "GET",
          expectedStatus: 200,
          maxRetries: 1,
          thinkTimeSeconds: 1,
        },
      ],
    };

    const serialized = serializeConfig(configWithoutProfiles);
    
    // Verify no profile properties are present
    expect(serialized).not.toContain("loadtest:");
    expect(serialized).not.toContain("stresstest:");
    expect(serialized).not.toContain("capacitytest:");
    expect(serialized).not.toContain("stabilitytest:");

    // Verify the endpoint structure is still valid
    expect(serialized).toContain("url:");
    expect(serialized).toContain("method:");
  });

  it("8.1.10: should match runner's filter behavior for multiple profiles", async () => {
    const imported = await import(`${tempConfigPath}?cache=${Date.now()}`);
    const config = imported.default;

    // Simulate runner's logic: filter by each TEST_TYPE
    const loadtestEndpoints = config.endpoints.filter((ep: any) => ep["loadtest"]);
    const stresstestEndpoints = config.endpoints.filter((ep: any) => ep["stresstest"]);
    const capacitytestEndpoints = config.endpoints.filter((ep: any) => ep["capacitytest"]);
    const stabilitytestEndpoints = config.endpoints.filter((ep: any) => ep["stabilitytest"]);

    // Verify counts match expected profile distribution
    expect(loadtestEndpoints.length).toBe(1);
    expect(stresstestEndpoints.length).toBe(1);
    expect(capacitytestEndpoints.length).toBe(1);
    expect(stabilitytestEndpoints.length).toBe(1);

    // Verify endpoints are correctly assigned
    expect(loadtestEndpoints[0]).toBe(stresstestEndpoints[0]); // Same endpoint has both
    expect(capacitytestEndpoints[0]).toBe(stabilitytestEndpoints[0]); // Same endpoint has both
    expect(loadtestEndpoints[0]).not.toBe(capacitytestEndpoints[0]); // Different endpoints
  });

  it("8.2.1: should preserve all project custom metrics (Req 6.4)", () => {
    // Task 8.2: Verify all custom metrics from the runner are preserved
    // Validates Requirements 6.1, 6.2, 6.3, 6.4
    
    // Create config with all custom metrics from performancetest.js
    const configWithAllMetrics: Config = {
      endpoints: [
        {
          url: "https://example.test/api/all-metrics",
          method: "POST",
          expectedStatus: 200,
          maxRetries: 3,
          thinkTimeSeconds: 1,
          loadtest: {
            stages: [{ duration: "1m", target: 10 }],
            thresholds: {
              // Built-in K6 metrics (Req 6.1)
              http_req_duration: ["p(95) < 2000"],
              http_req_failed: ["rate < 0.01"],
              // Custom project metrics (Req 6.2, 6.3, 6.4)
              waiting_time: ["avg < 1600"],
              Errors: ["count < 5"],
              Total_Reqs: ["count > 0"],
              retries: ["count < 10"],
              transaction_duration: ["avg < 2000"],
              transactions_per_second: ["rate > 1"],
              active_vus: ["avg > 0"],
            },
          },
        },
      ],
    };

    const serialized = serializeConfig(configWithAllMetrics);

    // Verify all built-in metrics are preserved exactly
    expect(serialized).toContain("http_req_duration:");
    expect(serialized).toContain("http_req_failed:");

    // Verify all custom metrics are preserved exactly (case-sensitive)
    expect(serialized).toContain("waiting_time:");
    expect(serialized).toContain("Errors:");
    expect(serialized).toContain("Total_Reqs:");
    expect(serialized).toContain("retries:");
    expect(serialized).toContain("transaction_duration:");
    expect(serialized).toContain("transactions_per_second:");
    expect(serialized).toContain("active_vus:");

    // Verify threshold expressions are preserved
    expect(serialized).toContain('"avg < 1600"');
    expect(serialized).toContain('"count < 5"');
    expect(serialized).toContain('"count > 0"');
    expect(serialized).toContain('"count < 10"');
    expect(serialized).toContain('"avg < 2000"');
    expect(serialized).toContain('"rate > 1"');
    expect(serialized).toContain('"avg > 0"');
  });
});
